<link rel="stylesheet" href="/assets/css/supplies.css?v=<?= filemtime($suppliesCss) ?>">
<section class="content-card"><div class="section-heading"><div><span class="eyebrow">Insumo</span><h2><?= $h($supply['name']) ?></h2><p>Identificação do lote em uso, validade e situação operacional.</p></div><div class="heading-actions"><a class="button button-secondary" href="/admin/supplies">Voltar</a><a class="button" href="/admin/supplies/lots/create?supply_id=<?= (int)$supply['id'] ?>">Novo Lote</a></div></div>
