<?php foreach($lots as $lot): ?><tr class="<?= !empty($lot['is_in_use'])?'lot-row-in-use':'' ?>"><td><strong><?= $h($lot['lot_number']) ?></strong></td><td><div class="lot-state-badges"><?php if(!empty($lot['is_in_use'])): ?><span class="lot-badge lot-badge-in-use">Em uso</span><?php else: ?><span class="lot-badge lot-badge-available">Disponível</span><?php endif; ?><?php if(!empty($lot['is_in_use'])&&$lot['validity']['key']==='expired'): ?><span class="lot-badge lot-badge-risk">Vencido</span><?php endif; ?></div></td><td><?= date('d/m/Y',strtotime($lot['expiration_date'])) ?></td><td><span class="validity validity-<?= $lot['validity']['key'] ?>"><?= $lot['validity']['label'] ?></span></td><td><?= $lot['received_at']?date('d/m/Y',strtotime($lot['received_at'])):'—' ?></td><td><?= $lot['quantity_initial']!==null?$h($lot['quantity_initial']):'—' ?></td><td><?= $lot['quantity_available']!==null?$h($lot['quantity_available']):'—' ?></td><td><span class="status status-<?= $lot['status'] ?>"><?= $h($statusLabels[$lot['status']]??$lot['status']) ?></span></td><td><a class="table-action" href="/admin/supplies/lots/edit?id=<?= (int)$lot['id'] ?>">Editar</a></td></tr><?php endforeach; ?>
<?php if(!$lots): ?><tr><td class="empty" colspan="9">Nenhum lote cadastrado para este insumo.</td></tr><?php endif; ?></tbody></table></div></section>
